html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Nota de entrega (remisión). Diseño: templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Nota de entrega") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{%- set entrega = direccion_lineas(doc.shipping_address_name) if doc.shipping_address_name and doc.shipping_address_name != doc.customer_address else [] -%}
{{ oc.datos(doc, {"etiqueta": "Cliente", "nombre": doc.customer_name or doc.customer, "rfc": rfc_tercero("Customer", doc.customer), "direccion": direccion_lineas(doc.customer_address)},
    [("Fecha", fecha_corta(doc.posting_date)),
     ("Orden de venta", (doc.items[0].against_sales_order if doc.items else None)),
     ("Lote", doc.get("lote_ref")),
     ("Entregar en", entrega | join(", ")),
     ("Piezas", cantidad_uom(doc.total_qty) if doc.total_qty else None)]) }}
{{ oc.tabla_articulos(doc, mostrar_peso=(doc.items | selectattr("total_weight") | list | length > 0)) }}
{{ oc.cierre(doc, mostrar_pagos=false) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
